import numpy as np, os,re
def clusters(A,col,n):
    # connected components via flood fill, return list of cell lists for given colors
    H,W=A.shape; seen=np.zeros_like(A,bool); comps={}
    from collections import deque
    for r in range(H):
        for c in range(W):
            if A[r,c]==col and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<H and 0<=xx<W and A[yy,xx]==col and not seen[yy,xx]:
                                seen[yy,xx]=True;q.append((yy,xx))
                comps[frozenset(comp)]=comp
    return comps
